import React, { useState } from 'react';
import { NavLink, useNavigate } from 'react-router-dom';
import { useSelector } from 'react-redux';

const Navbar = () => {
  const state = useSelector(state => state.handleCart);
  const isLoggedIn = !!localStorage.getItem('token');
  const navigate = useNavigate();
  const [isOpen, setIsOpen] = useState(false);
  const totalItems = state.items.reduce((sum, item) => sum + item.qty, 0);

  const handleLogout = () => {
    localStorage.removeItem('token');
    navigate('/login');
  };

  const toggleMenu = () => {
    setIsOpen(!isOpen);
  };

  return (
    <nav className="navbar navbar-expand-lg navbar-light bg-light py-3 sticky-top">
      <div className="container">
        <NavLink className="navbar-brand fw-bold fs-4 px-2" to="/"> Team 4 - Wood</NavLink>
        <button 
          className="navbar-toggler" 
          type="button" 
          onClick={toggleMenu}
          aria-controls="navbarSupportedContent" 
          aria-expanded={isOpen ? "true" : "false"} 
          aria-label="Toggle navigation"
        >
          <span className="navbar-toggler-icon"></span>
        </button>

        <div className={`collapse navbar-collapse ${isOpen ? 'show' : ''}`} id="navbarSupportedContent">
          <ul className="navbar-nav m-auto my-2 text-center">
            <li className="nav-item">
              <NavLink className="nav-link" to="/" onClick={() => setIsOpen(false)}>Trang chủ</NavLink>
            </li>
            <li className="nav-item">
              <NavLink className="nav-link" to="/product" onClick={() => setIsOpen(false)}>Sản phẩm</NavLink>
            </li>
            <li className="nav-item">
              <NavLink className="nav-link" to="/about" onClick={() => setIsOpen(false)}>Giới thiệu</NavLink>
            </li>
            <li className="nav-item">
              <NavLink className="nav-link" to="/contact" onClick={() => setIsOpen(false)}>Liên hệ</NavLink>
            </li>
          </ul>
          <div className="buttons text-center">
            {!isLoggedIn ? (
              <>
                <NavLink to="/login" className="btn btn-outline-dark m-2" onClick={() => setIsOpen(false)}>
                  <i className="fa fa-sign-in-alt mr-1"></i> Đăng nhập
                </NavLink>
                <NavLink to="/register" className="btn btn-outline-dark m-2" onClick={() => setIsOpen(false)}>
                  <i className="fa fa-user-plus mr-1"></i> Đăng ký
                </NavLink>
              </>
            ) : (
              <>
                <NavLink to="/cart" className="btn btn-outline-dark m-2" onClick={() => setIsOpen(false)}>
                  <i className="fa fa-cart-shopping mr-1"></i> Giỏ hàng ({totalItems || 0})
                </NavLink>
                <NavLink to="/account" className="btn btn-outline-dark m-2" onClick={() => setIsOpen(false)}>
                  <i className="fa fa-user mr-1"></i> Tài khoản
                </NavLink>
                <NavLink to="/admin" className="btn btn-outline-dark m-2" onClick={() => setIsOpen(false)}>
                  <i className="fa fa-lock mr-1"></i> Admin
                </NavLink>
                <button onClick={handleLogout} className="btn btn-outline-dark m-2">
                  <i className="fa fa-sign-out-alt mr-1"></i> Đăng xuất
                </button>
              </>
            )}
          </div>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;