import React, { useState, useEffect } from "react";
import axios from "axios";
import { useDispatch } from "react-redux";
import { addCart } from "../redux/action";
import Skeleton from "react-loading-skeleton";
import "react-loading-skeleton/dist/skeleton.css";
import { Link, useNavigate } from "react-router-dom";
import toast from "react-hot-toast";

const BASE_URL = "http://thanhvu1406-001-site1.qtempurl.com";

const Products = () => {
  const [products, setProducts] = useState([]);
  const [filteredProducts, setFilteredProducts] = useState([]);
  const [loading, setLoading] = useState(false);
  const dispatch = useDispatch();
  const navigate = useNavigate();

  useEffect(() => {
    const fetchProducts = async () => {
      setLoading(true);
      try {
        const response = await axios.get(`${BASE_URL}/api/SanPham`);
        if (response.data.success) {
          setProducts(response.data.data);
          setFilteredProducts(response.data.data);
        } else {
          toast.error("Không có sản phẩm nào");
        }
      } catch (error) {
        toast.error("Lỗi khi tải sản phẩm: " + error.message);
      }
      setLoading(false);
    };
    fetchProducts();
  }, []);

  const addProductToCart = (product) => {
    const token = localStorage.getItem('token');
    if (!token) {
      toast.error("Vui lòng đăng nhập để thêm vào giỏ hàng!");
      navigate('/login');
      return;
    }
    dispatch(addCart(product));
    toast.success("Đã thêm vào giỏ hàng");
  };

  const filterByCategory = (category) => {
    setFilteredProducts(category ? products.filter((item) => item.maDanhMuc === category) : products);
  };

  const formatCurrency = (price) => {
    return new Intl.NumberFormat("vi-VN", {
      style: "currency",
      currency: "VND",
      minimumFractionDigits: 0,
    }).format(price).replace("VND", "VNĐ");
  };

  // Hàm xử lý URL ảnh để tránh lỗi 404
  const getImageUrl = (imagePath) => {
    if (!imagePath) return "/default-product.jpg";
    if (imagePath.startsWith("http")) return imagePath;
    return `${BASE_URL}${imagePath.startsWith("/") ? imagePath : `/uploads/${imagePath}`}`;
  };

  return (
    <div className="container my-3 py-3">
      <h2 className="text-center">Sản phẩm mới nhất</h2>
      <hr />
      <div className="text-center py-3">
        <button className="btn btn-outline-primary m-2" onClick={() => filterByCategory("")}>Tất cả</button>
        <button className="btn btn-outline-primary m-2" onClick={() => filterByCategory("TQA")}>TỦ QUẦN ÁO</button>
        <button className="btn btn-outline-primary m-2" onClick={() => filterByCategory("BLV")}>BÀN</button>
        <button className="btn btn-outline-primary m-2" onClick={() => filterByCategory("BG")}>TỦ NHỎ</button>
        <button className="btn btn-outline-primary m-2" onClick={() => filterByCategory("DT")}>KHÁC</button>
      </div>
      <div className="row">
        {loading ? (
          <Skeleton count={6} height={300} />
        ) : (
          filteredProducts.map((product) => (
            <div key={product.maSanPham} className="col-lg-4 col-md-6 col-sm-12 mb-4">
              <div className="card h-100 text-center">
                <img
                  className="card-img-top p-3"
                  src={getImageUrl(product.hinhAnh)}
                  alt={product.tenSanPham}
                  height={250}
                  onError={(e) => { e.target.src = "/default-product.jpg"; }}
                />
                <div className="card-body d-flex flex-column">
                  <h5 className="card-title">{product.tenSanPham}</h5>
                  <p className="card-text flex-grow-1">{product.mota || "Không có mô tả"}</p>
                  <p className="text-danger fw-bold">{formatCurrency(product.gia)}</p>
                  <div className="mt-auto">
                    <Link to={`/product/${product.maSanPham}`} className="btn btn-primary me-2">Xem ngay</Link>
                    <button className="btn btn-success" onClick={() => addProductToCart(product)}>Thêm giỏ hàng</button>
                  </div>
                </div>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default Products;
